// CONFIGURAÇÃO
const DATASTORE_KEY = "contador_casos_criticos";

const dataStore = $getWorkflowStaticData('global');

if (!dataStore[DATASTORE_KEY]) {
  dataStore[DATASTORE_KEY] = 0;
}

dataStore[DATASTORE_KEY]++;

const contador = dataStore[DATASTORE_KEY];

let idCaso = "CRIT-" + String(contador).padStart(4, "0");
let protocoloBV = "";

const mensagem = $json.message.text;
const partes = mensagem.split("\n");

const match = mensagem.match(/(CRIT-\d+)\s+BV\s+(\d+)/i);

if (match) {
  idCaso = match[1];
  protocoloBV = match[2];
}

function limparTexto(texto, regex) {
  if (!texto) return "";
  return texto.replace(regex, "").trim();
}

const protocolo = limparTexto(partes[0], /Protocolo\s*N1\s*:/i);
const cliente = limparTexto(partes[1], /Código\s*Cliente\s*:/i);
const assunto = limparTexto(partes[2], /Assunto\s*Caso\s*:/i);
const descricao = limparTexto(partes[3], /Detalhamento\s*Caso\s*:/i);
const motivo = limparTexto(partes[4], /Motivo\s*Escalonamento\s*:/i);

const timestamp = $json.message.date;
const dataObj = new Date(timestamp * 1000);
const data = dataObj.toLocaleDateString("pt-BR", { timeZone: "America/Sao_Paulo" });
const hora = dataObj.toLocaleTimeString("pt-BR", { timeZone: "America/Sao_Paulo" });

// Usa nome completo (first_name + last_name) para match correto com MAPA_EMAILS
const firstName = ($json.message.from.first_name || '').trim();
const lastName = ($json.message.from.last_name || '').trim();
const responsavel = [firstName, lastName].filter(Boolean).join(' ');

return [
{
json: {
ID_Caso: idCaso,
Protocolo_BV: protocoloBV,
Data_Abertura: data,
Hora_Abertura: hora,
Protocolo: protocolo,
Codigo_Cliente: cliente,
Assunto: assunto,
Descricao: descricao,
Responsavel: responsavel,
Status: "Aberto",
Dias_Aberto: 0,
Timestamp_Abertura: timestamp
}
}
];

// Mapeia o Responsável para o e-mail de destino
const MAPA_EMAILS = {
  'Rodrigo Bertolini': 'rodrigo.bertolini@fazcapital.com.br',
  'Lucas Boeira': 'lucas.boeira@fazcapital.com.br',
  'Allini Pianca': 'allini.pianca@fazcapital.com.br',
  'Athos Baruk': 'athos.baruk@fazcapital.com.br',
  'Fabio Borges': 'fabio.borges@fazcapital.com.br'
};

// Busca e-mail por nome exato ou parcial (ex: só primeiro ou último nome)
function findEmail(nome) {
  if (!nome) return '';
  // Tentativa 1: match exato
  if (MAPA_EMAILS[nome]) return MAPA_EMAILS[nome];
  // Tentativa 2: alguma palavra do nome bate com parte de uma chave do mapa
  const nomeLower = nome.toLowerCase();
  for (const [chave, email] of Object.entries(MAPA_EMAILS)) {
    const chaveLower = chave.toLowerCase();
    // se o valor da planilha está contido no nome completo do mapa
    if (chaveLower.includes(nomeLower)) return email;
    // se alguma palavra do mapa está contida no valor da planilha
    const palavras = chaveLower.split(' ');
    if (palavras.some(p => p === nomeLower)) return email;
  }
  return '';
}

const responsavel = ($json['Responsável'] || $('Code in JavaScript').item.json.Responsavel || '').split('|')[0].trim();
const emailDest = findEmail(responsavel);

if (!emailDest) return [];

const idCaso    = $json['ID Caso']    || $('Code in JavaScript').item.json.ID_Caso    || '';
const status    = $('Code in JavaScript').item.json.Status || $json['Status'] || '';
const protocolo = $json['Protocolo N1'] || $('Code in JavaScript').item.json.Protocolo || '';
const cliente   = $json['Código Cliente'] || $('Code in JavaScript').item.json.Codigo_Cliente || '';
const assunto   = $json['Assunto']    || $('Code in JavaScript').item.json.Assunto    || '';
const descricao = $json['Descrição']  || $('Code in JavaScript').item.json.Descricao  || '';

const corpo =
  'Prezado(a),\n\n' +
  '🚨 Caso Crítico registrado! \n\n' +
  'As tratativas e atualizações deste caso serão realizadas por este e-mail.\n\n' +
  'Caso possua anexos ou novas informações, envie por este e-mail para registrar e complementar o caso.\n\n\n\n' +
  'ID: ' + idCaso + '\n' +
  'Status: ' + status + '\n\n' +
  '📌 Protocolo: ' + protocolo + '\n' +
  '👤 Cliente: ' + cliente + '\n\n' +
  '📝 Assunto Caso: ' + assunto + '\n\n' +
  '📄 Descrição: ' + descricao + '\n\n\n\n\nAtenciosamente,\n\n';

return [{
  json: {
    ...$json,
    email_destinatario: emailDest,
    draft_body: {
      subject: '[SUBIR BV] ' + idCaso + ' | Cliente ' + cliente + ' | ' + assunto,
      body: {
        contentType: 'Text',
        content: corpo
      },
      toRecipients: [
        { emailAddress: { address: emailDest } }
      ],
      ccRecipients: [
        { emailAddress: { address: 'lucas.boeira@fazcapital.com.br' } }
      ]
    }
  }
}];

